import json,pathlib,re
p=pathlib.Path('plans/multi-raft');targets={};target=None
for line in (p/'evidence/MR-11-peer-list.log').read_text().splitlines():
 m=re.search(r'Running (?:tests/(\w+)\.rs|unittests .+) \(',line)
 if m:target=m.group(1) or 'cellar_lib';targets[target]=set()
 elif target is not None and (m:=re.fullmatch(r'(\S+): test',line)):targets[target].add(m.group(1))
assert {'raft::mailbox::tests::receiver_teardown_joins_an_admitted_late_sender','raft::mailbox::tests::receiver_does_not_retain_its_producers'} <= targets['cellar_lib']
assert 'control_capacity_survives_unpolled_business_waiters' in targets['native_raft_host']
new_native={name for name in targets['native_raft_directory'] if name.startswith('native::inspection::')}
assert len(new_native)==2
new_unit={name for name in targets['cellar_lib'] if name.startswith(('raft::inspection_wire::tests::','raft::transport::inspections::tests::','raft::transport::tests::directory::inspection::'))}
assert len(new_unit)==10

tasks=json.loads((p/'tasks.json').read_text())['tasks'];mr11=next(t for t in tasks if t['id']=='MR-11');required={t['name'] for t in mr11['test_cases']}
assert required-targets['native_raft_membership']=={'automatic_no_traffic_repair','leader_balance_with_lag'}
mr10=next(t for t in tasks if t['id']=='MR-10');assert {t['name'] for t in mr10['test_cases']} <= targets['native_raft_snapshot']
print(json.dumps({'new_peer_cases_listed':12,'mr11_required_present':5,'mr11_required_total':7,'mr10_inventory':'passed','full_mr11_inventory_qualified':False}))
